public class InventoryController {
    public Donations submitDonation(Donations donation, UserAccount user) {
        requirePermission(user, user != null && user.canEnterRecords(),
                "User does not have permission to submit donations.");
        validateDonation(donation);
        requireDraft(donation.getStatus());
        return donation;
    }

    public int approveDonation(Donations donation, UserAccount approver) {
        requirePermission(approver, approver != null && approver.canManageRecords(),
                "User does not have permission to approve donations.");
        validateDonation(donation);
        requireDraft(donation.getStatus());

        Inventory inventory = donation.getInventory();
        int updatedQuantity = Math.addExact(inventory.getQuantity(), donation.getQuantity());
        inventory.setQuantity(updatedQuantity);
        donation.approve();
        return updatedQuantity;
    }

    public void rejectDonation(Donations donation, UserAccount approver) {
        requirePermission(approver, approver != null && approver.canManageRecords(),
                "User does not have permission to reject donations.");
        validateDonation(donation);
        donation.reject();
    }

    public Distribution submitDistribution(Distribution distribution, UserAccount user) {
        requirePermission(user, user != null && user.canEnterRecords(),
                "User does not have permission to submit distributions.");
        validateDistribution(distribution);
        requireDraft(distribution.getStatus());
        return distribution;
    }

    public int approveDistribution(Distribution distribution, UserAccount approver) {
        requirePermission(approver, approver != null && approver.canApproveDistributions(),
                "User does not have permission to approve distributions.");
        validateDistribution(distribution);
        requireDraft(distribution.getStatus());

        Inventory inventory = distribution.getInventory();
        if (distribution.getQuantity() > inventory.getQuantity()) {
            throw new IllegalArgumentException("Distribution quantity exceeds available inventory.");
        }

        int updatedQuantity = inventory.getQuantity() - distribution.getQuantity();
        inventory.setQuantity(updatedQuantity);
        distribution.approve();
        return updatedQuantity;
    }

    public void rejectDistribution(Distribution distribution, UserAccount approver) {
        requirePermission(approver, approver != null && approver.canApproveDistributions(),
                "User does not have permission to reject distributions.");
        validateDistribution(distribution);
        distribution.reject();
    }

    private void validateDonation(Donations donation) {
        if (donation == null) {
            throw new IllegalArgumentException("Donation cannot be null.");
        }
        if (donation.getInventory() == null) {
            throw new IllegalArgumentException("Donation must be linked to an inventory item.");
        }
        if (donation.getQuantity() <= 0) {
            throw new IllegalArgumentException("Donation quantity must be positive.");
        }
    }

    private void validateDistribution(Distribution distribution) {
        if (distribution == null) {
            throw new IllegalArgumentException("Distribution cannot be null.");
        }
        if (distribution.getInventory() == null) {
            throw new IllegalArgumentException("Distribution must be linked to an inventory item.");
        }
        if (distribution.getBeneficiary() == null) {
            throw new IllegalArgumentException("Distribution must be linked to a beneficiary.");
        }
        if (distribution.getQuantity() <= 0) {
            throw new IllegalArgumentException("Distribution quantity must be positive.");
        }
    }

    private void requireDraft(TransactionStatus status) {
        if (status != TransactionStatus.DRAFT) {
            throw new IllegalStateException("Only draft transactions can be submitted or approved.");
        }
    }

    private void requirePermission(UserAccount user, boolean permitted, String message) {
        if (user == null || !permitted) {
            throw new SecurityException(message);
        }
    }
}

