        DisasterController disasterController = new DisasterController();
        Disaster disaster = disasterController.createDisaster("D1", "Flood", "Flood", "Barangay A", "2026-10-14", "Active");
        disasterController.updateDisasterStatus(disaster, "Closed");
        if (!"Closed".equals(disaster.getStatus())) throw new AssertionError();

        Beneficiaries beneficiary = new BeneficiaryController().registerBeneficiary(
                "B1", "Household", "Barangay A", 4, "Food", disaster);
        expectFailure(() -> new BeneficiaryController().registerBeneficiary(
                "B2", "Household", "Barangay A", 2, "Water", null), IllegalArgumentException.class);

        UserAccount admin = new AdminAccount("A1", "Admin", "admin");
        UserAccount official = new BarangayOfficialAccount("O1", "Official", "official");
        UserAccount encoder = new EncoderAccount("E1", "Encoder", "encoder");
        UserAccountController userController = new UserAccountController();
        if (!(userController.createAccount("E2", "New Encoder", "new-encoder", UserAccount.Role.ENCODER, admin)
                instanceof EncoderAccount)) throw new AssertionError();
        expectFailure(() -> userController.createAccount("E3", "New Encoder", "another", UserAccount.Role.ENCODER, encoder), SecurityException.class);

        DonationController donationController = new DonationController();
