        if (inventory.getQuantity() != 15) throw new AssertionError("Donation approval failed");

        DistributionController distributionController = new DistributionController();
        Distribution distribution = new Distribution("DS1", 3, "2026-10-14", beneficiary, inventory);
        distributionController.submitDistribution(distribution, encoder);
        distributionController.approveDistribution(distribution, official);
        if (inventory.getQuantity() != 12) throw new AssertionError("Distribution approval failed");

        Reports report = new ReportController().createReportRecord("RP1", "Summary", "2026-10-14", inventory, disaster, distribution);
        if (report.getInventory() != inventory || report.getDistribution() != distribution) throw new AssertionError();
        Audits audit = new AuditLogController().createAuditRecord("AU1", "Distribution approved", "2026-10-14T10:00", official, null, distribution);
        if (audit.getUser() != official || audit.getDistribution() != distribution) throw new AssertionError();
