import java.util.List;
import java.util.Objects;

public class Donations {
    private String donationId;
    private Donor donor;
    private String donationDate;
    private String receivingLocation;
    private String deliveryReference;
    private UserAccount receivedBy;
    private final List<TransactionItem> items = new ArrayList<>();
    private TransactionStatus status = TransactionStatus.DRAFT;

    public Donations(String donationId, Donor donor, String donationDate,
            String receivingLocation, String deliveryReference) {
        this.donationId = donationId;
        this.donor = donor;
        this.donationDate = donationDate;
        this.receivingLocation = receivingLocation;
        this.deliveryReference = deliveryReference;
    }

    public String getDonationId() {
        return donationId;
    }

    public void setDonationId(String donationId) {
        requireDraft();
        this.donationId = donationId;
    }

    public Donor getDonor() {
        return donor;
    }

    public void setDonor(Donor donor) {
        requireDraft();
        this.donor = donor;
    }

    public String getDonationDate() {
        return donationDate;
    }

    public void setDonationDate(String donationDate) {
        requireDraft();
        this.donationDate = donationDate;
    }

    public String getReceivingLocation() {
        return receivingLocation;
    }

    public void setReceivingLocation(String receivingLocation) {
        requireDraft();
        this.receivingLocation = receivingLocation;
    }

    public String getDeliveryReference() {
        return deliveryReference;
    }

    public void setDeliveryReference(String deliveryReference) {
        requireDraft();
        this.deliveryReference = deliveryReference;
    }

    public UserAccount getReceivedBy() {
        return receivedBy;
    }

    public List<TransactionItem> getItems() {
        return Collections.unmodifiableList(new ArrayList<>(items));
    }

    public void addItem(TransactionItem item) {
        requireDraft();
        items.add(Objects.requireNonNull(item, "item"));
    }

    public TransactionStatus getStatus() {
        return status;
    }

    public Donations submit(UserAccount submitter) {
        requirePermission(submitter, submitter != null && submitter.canEnterRecords(),
                "User does not have permission to submit donations.");
        validate();
        requireDraft();
        return this;
    }

    public void approve(UserAccount approver) {
        requirePermission(approver, approver != null && approver.canManageRecords(),
                "User does not have permission to approve donations.");
        validate();
        requireDraft();

        for (TransactionItem item : items) {
            if (isFirstOccurrence(item)) {
                item.getInventory().validateStockAddition(totalQuantityFor(item.getInventory()));
            }
        }
        for (TransactionItem item : items) {
            item.getInventory().addStock(item.getQuantity());
        }

        receivedBy = approver;
        status = TransactionStatus.APPROVED;
    }

    public void reject(UserAccount approver) {
        requirePermission(approver, approver != null && approver.canManageRecords(),
                "User does not have permission to reject donations.");
        requireDraft();
        status = TransactionStatus.REJECTED;
    }

    private void validate() {
        if (donor == null) {
            throw new IllegalArgumentException("Donation must be linked to a donor.");
        }
        if (items.isEmpty()) {
            throw new IllegalArgumentException("Donation must contain at least one item.");
        }
    }

    private int totalQuantityFor(Inventory inventory) {
        int total = 0;
        for (TransactionItem item : items) {
            if (item.getInventory() == inventory) {
                total = Math.addExact(total, item.getQuantity());
            }
        }
        return total;
    }

    private boolean isFirstOccurrence(TransactionItem candidate) {
        for (TransactionItem item : items) {
            if (item == candidate) {
                return true;
            }
            if (item.getInventory() == candidate.getInventory()) {
                return false;
            }
        }
        return false;
    }

    private void requireDraft() {
        if (status != TransactionStatus.DRAFT) {
            throw new IllegalStateException("Only draft donations can be changed.");
        }
    }

    private void requirePermission(UserAccount user, boolean permitted, String message) {
        if (user == null || !permitted) {
            throw new SecurityException(message);
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public class Distribution {
    private String distributionId;
    private String distributionDate;
    private Disaster disaster;
    private Beneficiaries beneficiary;
    private String releaseLocation;
    private String receiptReference;
    private UserAccount releasedBy;
    private final List<TransactionItem> items = new ArrayList<>();
    private TransactionStatus status = TransactionStatus.DRAFT;

    public Distribution(String distributionId, String distributionDate, Disaster disaster,
            Beneficiaries beneficiary, String releaseLocation, String receiptReference) {
        this.distributionId = distributionId;
        this.distributionDate = distributionDate;
        this.disaster = disaster;
        this.beneficiary = beneficiary;
        this.releaseLocation = releaseLocation;
        this.receiptReference = receiptReference;
    }

    public String getDistributionId() {
        return distributionId;
    }

    public void setDistributionId(String distributionId) {
        requireDraft();
        this.distributionId = distributionId;
    }

    public String getDistributionDate() {
        return distributionDate;
    }

    public void setDistributionDate(String distributionDate) {
        requireDraft();
        this.distributionDate = distributionDate;
    }

    public Disaster getDisaster() {
        return disaster;
    }

    public void setDisaster(Disaster disaster) {
        requireDraft();
        this.disaster = disaster;
    }

    public Beneficiaries getBeneficiary() {
        return beneficiary;
    }

    public void setBeneficiary(Beneficiaries beneficiary) {
        requireDraft();
        this.beneficiary = beneficiary;
    }

    public String getReleaseLocation() {
        return releaseLocation;
    }

    public void setReleaseLocation(String releaseLocation) {
        requireDraft();
        this.releaseLocation = releaseLocation;
    }

    public String getReceiptReference() {
        return receiptReference;
    }

    public void setReceiptReference(String receiptReference) {
        requireDraft();
        this.receiptReference = receiptReference;
    }

    public UserAccount getReleasedBy() {
        return releasedBy;
    }

    public List<TransactionItem> getItems() {
        return Collections.unmodifiableList(new ArrayList<>(items));
    }

    public void addItem(TransactionItem item) {
        requireDraft();
        items.add(Objects.requireNonNull(item, "item"));
    }

    public TransactionStatus getStatus() {
        return status;
    }

    public Distribution submit(UserAccount submitter) {
        requirePermission(submitter, submitter != null && submitter.canEnterRecords(),
                "User does not have permission to submit distributions.");
        validate();
        requireDraft();
        return this;
    }

    public void approve(UserAccount approver) {
        requirePermission(approver, approver != null && approver.canApproveDistributions(),
                "User does not have permission to approve distributions.");
        validate();
        requireDraft();

        for (TransactionItem item : items) {
            if (isFirstOccurrence(item)) {
                int requested = totalQuantityFor(item.getInventory());
                if (requested > item.getInventory().getQuantity()) {
                    throw new IllegalArgumentException("Distribution quantity exceeds available inventory.");
                }
            }
        }
        for (TransactionItem item : items) {
            item.getInventory().removeStock(item.getQuantity());
        }

        releasedBy = approver;
        status = TransactionStatus.APPROVED;
    }

    public void reject(UserAccount approver) {
        requirePermission(approver, approver != null && approver.canApproveDistributions(),
                "User does not have permission to reject distributions.");
        requireDraft();
        status = TransactionStatus.REJECTED;
    }

    private void validate() {
        if (disaster == null) {
            throw new IllegalArgumentException("Distribution must be linked to a disaster.");
        }
        if (beneficiary == null && (releaseLocation == null || releaseLocation.trim().isEmpty())) {
            throw new IllegalArgumentException("Distribution must identify a beneficiary or release location.");
        }
        if (beneficiary != null && beneficiary.getDisaster() != disaster) {
            throw new IllegalArgumentException("Beneficiary must belong to the selected disaster.");
        }
        if (items.isEmpty()) {
            throw new IllegalArgumentException("Distribution must contain at least one item.");
        }
        if (receiptReference == null || receiptReference.trim().isEmpty()) {
            throw new IllegalArgumentException("Distribution must include a receipt reference.");
        }
    }

    private int totalQuantityFor(Inventory inventory) {
        int total = 0;
        for (TransactionItem item : items) {
            if (item.getInventory() == inventory) {
                total = Math.addExact(total, item.getQuantity());
            }
        }
        return total;
    }

    private boolean isFirstOccurrence(TransactionItem candidate) {
        for (TransactionItem item : items) {
            if (item == candidate) {
                return true;
            }
            if (item.getInventory() == candidate.getInventory()) {
                return false;
            }
        }
        return false;
    }

    private void requireDraft() {
        if (status != TransactionStatus.DRAFT) {
            throw new IllegalStateException("Only draft distributions can be changed.");
        }
    }

    private void requirePermission(UserAccount user, boolean permitted, String message) {
        if (user == null || !permitted) {
            throw new SecurityException(message);
        }
    }
}

