import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;

public class MainFrame extends JFrame {
    private static final Color SIDEBAR = new Color(0x1F3A5F);
    private static final Color SELECTED = new Color(0x2E6DA4);

    private final UserAccount user;
    private final CardLayout cards = new CardLayout();
    private final JPanel content = new JPanel(cards);
    private final Map<String, RefreshablePanel> screens = new LinkedHashMap<>();
    private final Map<String, JButton> navButtons = new LinkedHashMap<>();

    public MainFrame(UserAccount user) {
        super("BarangayCare - " + DataAccess.workspaceName(user));
        this.user = user;
        setDefaultCloseOperation(EXIT_ON_CLOSE);

        screens.put("Dashboard", new DashboardPanel(user, this::showScreen));
        screens.put("Inventory", new InventoryPanel(user));
        screens.put("Disasters", new PlaceholderPanel("Disasters"));
        screens.put("Beneficiaries", new PlaceholderPanel("Beneficiaries"));
        screens.put("Donations", new PlaceholderPanel("Donations"));
        screens.put("Distribution", new PlaceholderPanel("Distribution"));
        screens.put("Reports", new PlaceholderPanel("Reports"));
        screens.put("Audit Logs", new PlaceholderPanel("Audit Logs"));
        if (user.canManageUsers()) {
            screens.put("User Administration", new PlaceholderPanel("User Administration"));
        }
        for (Map.Entry<String, RefreshablePanel> entry : screens.entrySet()) {
            content.add(entry.getValue(), entry.getKey());
        }

        setLayout(new BorderLayout());
        add(buildSidebar(), BorderLayout.WEST);
        add(content, BorderLayout.CENTER);
        setSize(1100, 680);
        setLocationRelativeTo(null);
        showScreen("Dashboard");
    }

    private JScrollPane buildSidebar() {
        JPanel sidebar = new JPanel();
        sidebar.setLayout(new BoxLayout(sidebar, BoxLayout.Y_AXIS));
        sidebar.setBackground(SIDEBAR);
        sidebar.setBorder(BorderFactory.createEmptyBorder(16, 12, 16, 12));

        JLabel brand = new JLabel("BarangayCare");
        brand.setForeground(Color.WHITE);
        brand.setFont(brand.getFont().deriveFont(Font.BOLD, 20f));
        sidebar.add(brand);
        JLabel who = new JLabel("<html>" + user.getName() + "<br>" + DataAccess.roleLabel(user) + "</html>");
        who.setForeground(new Color(0xC9D6E8));
        sidebar.add(Box.createRigidArea(new Dimension(0, 6)));
        sidebar.add(who);
        sidebar.add(Box.createRigidArea(new Dimension(0, 20)));

        for (String name : screens.keySet()) {
            JButton button = new JButton(name);
            button.setAlignmentX(LEFT_ALIGNMENT);
            button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 38));
            button.setHorizontalAlignment(JButton.LEFT);
            button.setForeground(Color.WHITE);
            button.setBackground(SIDEBAR);
            button.setOpaque(true);
            button.setBorderPainted(false);
            button.setFocusPainted(false);
            button.addActionListener(event -> showScreen(name));
            navButtons.put(name, button);
            sidebar.add(button);
            sidebar.add(Box.createRigidArea(new Dimension(0, 4)));
        }

        sidebar.add(Box.createVerticalGlue());
        JButton logout = new JButton("Log out");
        logout.setAlignmentX(LEFT_ALIGNMENT);
        logout.setMaximumSize(new Dimension(Integer.MAX_VALUE, 38));
        logout.addActionListener(event -> {
            dispose();
            new LoginFrame().setVisible(true);
        });
        sidebar.add(logout);

        JScrollPane scrollPane = new JScrollPane(sidebar);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        scrollPane.setBorder(BorderFactory.createEmptyBorder());
        scrollPane.setPreferredSize(new Dimension(220, 0));
        return scrollPane;
    }

    private void showScreen(String name) {
        RefreshablePanel screen = screens.get(name);
        if (screen == null) {
            return;
        }
        screen.refresh();
        cards.show(content, name);
        for (Map.Entry<String, JButton> entry : navButtons.entrySet()) {
            entry.getValue().setBackground(entry.getKey().equals(name) ? SELECTED : SIDEBAR);
        }
    }
}

package GUI;

import LIB.Inventory;
import LIB.UserAccount;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.awt.GridLayout;
import java.sql.SQLException;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;

class DashboardPanel extends RefreshablePanel {
    private final UserAccount user;
    private final JLabel itemTypesValue;
    private final JLabel totalUnitsValue;
    private final JLabel lowStockValue;
    private final DefaultListModel<String> lowStockModel = new DefaultListModel<>();
    private final JLabel statusLabel = new JLabel(" ");

    DashboardPanel(UserAccount user, Consumer<String> navigator) {
        this.user = user;
        setLayout(new BorderLayout(0, 16));
        setBorder(BorderFactory.createEmptyBorder(24, 24, 24, 24));

        JPanel top = new JPanel(new BorderLayout());
        JLabel heading = new JLabel("Dashboard");
        heading.setFont(heading.getFont().deriveFont(Font.BOLD, 22f));
        top.add(heading, BorderLayout.NORTH);
        top.add(new JLabel("Workspace: " + DataAccess.workspaceName(user)), BorderLayout.SOUTH);
        add(top, BorderLayout.NORTH);

        JPanel center = new JPanel(new BorderLayout(0, 16));
        JPanel cardsRow = new JPanel(new GridLayout(1, 3, 16, 0));
        itemTypesValue = addCard(cardsRow, "Item types");
        totalUnitsValue = addCard(cardsRow, "Total units in stock");
        lowStockValue = addCard(cardsRow, "Low-stock items");
        center.add(cardsRow, BorderLayout.NORTH);

        JPanel lowPanel = new JPanel(new BorderLayout(0, 6));
        lowPanel.add(new JLabel("Items that need replenishing:"), BorderLayout.NORTH);
        lowPanel.add(new JScrollPane(new JList<>(lowStockModel)), BorderLayout.CENTER);
        center.add(lowPanel, BorderLayout.CENTER);
        add(center, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        JButton viewInventory = new JButton("View inventory");
        viewInventory.addActionListener(event -> navigator.accept("Inventory"));
        JPanel buttons = new JPanel();
        buttons.add(viewInventory);
        bottom.add(buttons, BorderLayout.WEST);
        statusLabel.setForeground(new Color(0xB00020));
        bottom.add(statusLabel, BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);
    }

    private JLabel addCard(JPanel row, String caption) {
        JPanel card = new JPanel(new BorderLayout());
        card.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(0xC9D6E8)),
                BorderFactory.createEmptyBorder(14, 16, 14, 16)));
        JLabel value = new JLabel("0");
        value.setFont(value.getFont().deriveFont(Font.BOLD, 28f));
        card.add(value, BorderLayout.CENTER);
        card.add(new JLabel(caption), BorderLayout.SOUTH);
        row.add(card);
        return value;
    }

    @Override
    void refresh() {
        try {
            List<Inventory> items = DataAccess.inventoryFor(user);
            int units = 0;
            int low = 0;
            lowStockModel.clear();
            for (Inventory item : items) {
                units += item.getQuantity();
                if (item.isLowStock()) {
                    low++;
                    lowStockModel.addElement(item.getItemName() + " - " + item.getQuantity() + " "
                            + item.getUnit() + " left (threshold " + item.getLowStockThreshold() + ")");
                }
            }
            itemTypesValue.setText(String.valueOf(items.size()));
            totalUnitsValue.setText(String.valueOf(units));
            lowStockValue.setText(String.valueOf(low));
            statusLabel.setText(" ");
        } catch (SQLException exception) {
            statusLabel.setText("Could not load data: " + exception.getMessage());
        }
    }
}

package GUI;

import LIB.Barangay;
import LIB.Inventory;
import LIB.InventoryBatch;
import LIB.InventoryController;
import LIB.UserAccount;
import java.awt.BorderLayout;
import java.awt.Font;
import java.awt.GridLayout;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTable;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.table.DefaultTableModel;

class InventoryPanel extends RefreshablePanel {
    private final UserAccount user;
    private final InventoryController controller = new InventoryController();
    private final DefaultTableModel tableModel = new DefaultTableModel(new String[] {
        "Item ID", "Item", "Category", "Quantity", "Unit", "Low-stock at", "Status", "Location", "Barangay"
    }, 0) {
        @Override
        public boolean isCellEditable(int row, int column) {
            return false;
        }
    };
    private final JTable table = new JTable(tableModel);
    private final JLabel statusLabel = new JLabel(" ");
    private List<Inventory> items = new ArrayList<>();

    InventoryPanel(UserAccount user) {
        this.user = user;
        setLayout(new BorderLayout(0, 12));
        setBorder(BorderFactory.createEmptyBorder(24, 24, 24, 24));

        JLabel heading = new JLabel("Inventory");
        heading.setFont(heading.getFont().deriveFont(Font.BOLD, 22f));
        add(heading, BorderLayout.NORTH);
        table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        table.setRowHeight(24);
        add(new JScrollPane(table), BorderLayout.CENTER);

        JPanel buttons = new JPanel();
        JButton addButton = new JButton("Add item");
        addButton.setEnabled(user.canEnterRecords());
        addButton.addActionListener(event -> addItem());
        JButton batchesButton = new JButton("View batches");
        batchesButton.addActionListener(event -> showBatches());
        JButton refreshButton = new JButton("Refresh");
        refreshButton.addActionListener(event -> refresh());
        buttons.add(addButton);
        buttons.add(batchesButton);
        buttons.add(refreshButton);

        JPanel bottom = new JPanel(new BorderLayout());
        bottom.add(buttons, BorderLayout.WEST);
        bottom.add(statusLabel, BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);
    }

    @Override
    void refresh() {
        try {
            items = DataAccess.inventoryFor(user);
            tableModel.setRowCount(0);
            for (Inventory item : items) {
                tableModel.addRow(new Object[] { item.getItemId(), item.getItemName(), item.getCategory(),
                        item.getQuantity(), item.getUnit(), item.getLowStockThreshold(),
                        item.isLowStock() ? "LOW STOCK" : "OK", item.getStorageLocation(),
                        item.getBarangay() == null ? "" : item.getBarangay().getName() });
            }
            statusLabel.setText(items.size() + " item(s)");
        } catch (SQLException exception) {
            statusLabel.setText("Could not load inventory: " + exception.getMessage());
        }
    }

    private void showBatches() {
        int row = table.getSelectedRow();
        if (row < 0) {
            JOptionPane.showMessageDialog(this, "Select an item first.");
            return;
        }
        Inventory item = items.get(table.convertRowIndexToModel(row));
        DefaultTableModel model = new DefaultTableModel(new String[] {
            "Batch ID", "Received", "Expiry", "Received qty", "Remaining qty"
        }, 0);
        for (InventoryBatch batch : item.getBatches()) {
            model.addRow(new Object[] { batch.getBatchId(), batch.getReceivedDate(), batch.getExpiryDate(),
                    batch.getReceivedQuantity(), batch.getRemainingQuantity() });
        }
        JTable batchTable = new JTable(model);
        JScrollPane scroll = new JScrollPane(batchTable);
        scroll.setPreferredSize(new java.awt.Dimension(560, 180));
        JOptionPane.showMessageDialog(this, scroll, "Batches - " + item.getItemName(), JOptionPane.PLAIN_MESSAGE);
    }

    private void addItem() {
        try {
            Barangay target = user.getBarangay();
            List<Barangay> choices = new ArrayList<>();
            JComboBox<String> barangayBox = null;
            if (user.getRole() == UserAccount.Role.ADMIN) {
                choices = DataAccess.BARANGAYS.findAll();
                if (choices.isEmpty()) {
                    JOptionPane.showMessageDialog(this, "There is no barangay workspace yet.");
                    return;
                }
                String[] names = new String[choices.size()];
                for (int index = 0; index < names.length; index++) {
                    names[index] = choices.get(index).getName();
                }
                barangayBox = new JComboBox<>(names);
            }

            JTextField nameField = new JTextField();
            JTextField categoryField = new JTextField("Food");
            JTextField unitField = new JTextField();
            JTextField thresholdField = new JTextField("0");
            JTextField locationField = new JTextField();
            JTextField quantityField = new JTextField("0");
            JTextField expiryField = new JTextField();

            JPanel form = new JPanel(new GridLayout(0, 2, 8, 8));
            if (barangayBox != null) {
                form.add(new JLabel("Barangay"));
                form.add(barangayBox);
            }
            form.add(new JLabel("Item name")); form.add(nameField);
            form.add(new JLabel("Category")); form.add(categoryField);
            form.add(new JLabel("Unit (e.g. sack, can)")); form.add(unitField);
            form.add(new JLabel("Low-stock threshold")); form.add(thresholdField);
            form.add(new JLabel("Storage location")); form.add(locationField);
            form.add(new JLabel("Opening stock quantity")); form.add(quantityField);
            form.add(new JLabel("Opening stock expiry (optional)")); form.add(expiryField);

            int result = JOptionPane.showConfirmDialog(this, form, "Add inventory item",
                    JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
            if (result != JOptionPane.OK_OPTION) {
                return;
            }
            if (barangayBox != null) {
                target = choices.get(barangayBox.getSelectedIndex());
            }
            if (nameField.getText().trim().isEmpty() || unitField.getText().trim().isEmpty()) {
                JOptionPane.showMessageDialog(this, "Item name and unit are required.");
                return;
            }

            int quantity = Integer.parseInt(quantityField.getText().trim());
            int threshold = Integer.parseInt(thresholdField.getText().trim());
            String expiry = expiryField.getText().trim();
            String itemId = "ITM-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
            Inventory item = controller.createInventoryItem(itemId, nameField.getText().trim(),
                    categoryField.getText().trim(), quantity, unitField.getText().trim(), threshold,
                    locationField.getText().trim(), expiry.isEmpty() ? null : expiry, target, user);
            DataAccess.INVENTORY.save(item);
            refresh();
        } catch (NumberFormatException exception) {
            JOptionPane.showMessageDialog(this, "Quantity and threshold must be whole numbers.");
        } catch (SecurityException | IllegalArgumentException exception) {
            JOptionPane.showMessageDialog(this, exception.getMessage());
        } catch (SQLException exception) {
            JOptionPane.showMessageDialog(this, "Could not save: " + exception.getMessage());
        }
    }
}

